1	// examples/autotune_demo/gemm_kernel.cu
2	// ===========================================================================
3	// A DELIBERATELY-NAIVE-by-default, parameterized tiled fp32 GEMM, built to
4	// demonstrate compile.py's autotuner leverage on a kernel that has NOT been
5	// hand-tuned. C[M,N] = A[M,K] * B[K,N], row-major, fp32.
6	//
7	// The four tuning knobs are exposed as compile.py-style `#ifndef SG_TUNED_*`
8	// guards so a `-DSG_TUNED_*` flag (emitted by compile.py's resolve_macros)
9	// overrides the in-source default. The defaults are chosen to be CORRECT but
10	// SLOW (a tiny 16x16 output tile with a 16-deep K strip and only 256 threads
11	// — essentially the textbook "shared-memory tile" at its least-effective
12	// shape, with no register blocking), so the autotuner has real headroom.
13	//
14	//   SG_TUNED_TILE_M   rows of C computed per block      (default 16)
15	//   SG_TUNED_TILE_N   cols of C computed per block       (default 16)
16	//   SG_TUNED_TILE_K   K-strip depth per main-loop step   (default 16)
17	//   SG_TUNED_BLOCK    threads per block                  (default 256)
18	//
19	// CORRECTNESS CONTRACT (holds for EVERY legal config the search explores):
20	//   * The kernel is a single shared-memory-tiled GEMM with FULL boundary
21	//     guards on M, N, and K, so it is numerically correct for ANY M, N, K and
22	//     ANY (TILE_M, TILE_N, TILE_K, BLOCK) satisfying the static_asserts below.
23	//   * Each thread computes exactly REG_TILE = (TILE_M*TILE_N)/BLOCK output
24	//     elements (a register micro-tile). We require BLOCK to divide
25	//     TILE_M*TILE_N (static_assert) so the work partitions evenly; the search
26	//     space (gemm_search_space.yaml) only ever offers legal combinations.
27	//   * Shared-memory footprint is (TILE_M*TILE_K + TILE_K*TILE_N) floats; the
28	//     largest legal combo in the search space stays well under 48 KB.
29	//
30	// The op is registered as a torch custom op `torch.ops.sg_demo.gemm(C, A, B)`
31	// via TORCH_LIBRARY, so the tune_hook can drive it with torch.ops.load_library
32	// (exactly like examples/toy_tune_project). The MATH is identical for every
33	// config (only tiling/launch geometry changes), so every variant must match
34	// the strict reference build's output — only elapsed_ms varies, which is what
35	// the autotuner minimizes.
36	// ===========================================================================
37	#include <torch/extension.h>
38	#include <cuda_runtime.h>
39	
40	#ifndef SG_TUNED_TILE_M
41	#define SG_TUNED_TILE_M 16
42	#endif
43	#ifndef SG_TUNED_TILE_N
44	#define SG_TUNED_TILE_N 16
45	#endif
46	#ifndef SG_TUNED_TILE_K
47	#define SG_TUNED_TILE_K 16
48	#endif
49	#ifndef SG_TUNED_BLOCK
50	#define SG_TUNED_BLOCK 256
51	#endif
52	
53	namespace {
54	
55	constexpr int TILE_M = SG_TUNED_TILE_M;
56	constexpr int TILE_N = SG_TUNED_TILE_N;
57	constexpr int TILE_K = SG_TUNED_TILE_K;
58	constexpr int BLOCK  = SG_TUNED_BLOCK;
59	
60	// Per-thread register micro-tile: each thread owns REG_TILE outputs of the
61	// TILE_M x TILE_N block tile. Must partition evenly.
62	constexpr int OUT_PER_TILE = TILE_M * TILE_N;
63	static_assert(OUT_PER_TILE % BLOCK == 0,
64	              "SG_TUNED_BLOCK must divide SG_TUNED_TILE_M*SG_TUNED_TILE_N "
65	              "(each thread computes an integer number of outputs)");
66	constexpr int REG_TILE = OUT_PER_TILE / BLOCK;
67	
68	// Shared-tile load also partitions over BLOCK threads (grid-stride guarded, so
69	// exact divisibility is NOT required, but keep tiles sane).
70	static_assert(TILE_M > 0 && TILE_N > 0 && TILE_K > 0 && BLOCK > 0,
71	              "all tuned tile/block dims must be positive");
72	static_assert(BLOCK <= 1024, "SG_TUNED_BLOCK exceeds the 1024 threads/block HW limit");
73	// 48 KB static smem ceiling (we do not opt into the dynamic >48KB attribute).
74	static_assert((TILE_M * TILE_K + TILE_K * TILE_N) * (int)sizeof(float) <= 48 * 1024,
75	              "tuned shared tile exceeds 48KB static smem");
76	
77	__global__ void gemm_tiled(const float* __restrict__ A,
78	                           const float* __restrict__ B,
79	                           float* __restrict__ C,
80	                           int M, int N, int K) {
81	    __shared__ float As[TILE_M][TILE_K];
82	    __shared__ float Bs[TILE_K][TILE_N];
83	
84	    const int block_row = blockIdx.y * TILE_M;  // first C row this block owns
85	    const int block_col = blockIdx.x * TILE_N;  // first C col this block owns
86	    const int tid = threadIdx.x;
87	
88	    // This thread owns REG_TILE elements of the block tile, laid out as a
89	    // contiguous strip starting at linear index (tid*REG_TILE) in row-major
90	    // (TILE_M x TILE_N) order. acc holds the running fp32 accumulators.
91	    float acc[REG_TILE];
92	#pragma unroll
93	    for (int r = 0; r < REG_TILE; ++r) acc[r] = 0.0f;
94	
95	    const int num_k_tiles = (K + TILE_K - 1) / TILE_K;
96	    for (int kt = 0; kt < num_k_tiles; ++kt) {
97	        const int k0 = kt * TILE_K;
98	
99	        // Cooperative, boundary-guarded load of As (TILE_M x TILE_K) and
100	        // Bs (TILE_K x TILE_N). Grid-stride over BLOCK threads so any BLOCK
101	        // legally fills the tile regardless of divisibility.
102	        for (int i = tid; i < TILE_M * TILE_K; i += BLOCK) {
103	            const int r = i / TILE_K;
104	            const int c = i % TILE_K;
105	            const int gr = block_row + r;
106	            const int gc = k0 + c;
107	            As[r][c] = (gr < M && gc < K) ? A[gr * K + gc] : 0.0f;
108	        }
109	        for (int i = tid; i < TILE_K * TILE_N; i += BLOCK) {
110	            const int r = i / TILE_N;
111	            const int c = i % TILE_N;
112	            const int gr = k0 + r;
113	            const int gc = block_col + c;
114	            Bs[r][c] = (gr < K && gc < N) ? B[gr * N + gc] : 0.0f;
115	        }
116	        __syncthreads();
117	
118	        // Multiply the loaded strip into each of this thread's REG_TILE outputs.
119	#pragma unroll
120	        for (int r = 0; r < REG_TILE; ++r) {
121	            const int lin = tid * REG_TILE + r;   // linear idx in block tile
122	            const int tr = lin / TILE_N;          // row within tile
123	            const int tc = lin % TILE_N;          // col within tile
124	            float s = acc[r];
125	#pragma unroll
126	            for (int kk = 0; kk < TILE_K; ++kk) {
127	                s += As[tr][kk] * Bs[kk][tc];
128	            }
129	            acc[r] = s;
130	        }
131	        __syncthreads();
132	    }
133	
134	    // Write back, boundary-guarded.
135	#pragma unroll
136	    for (int r = 0; r < REG_TILE; ++r) {
137	        const int lin = tid * REG_TILE + r;
138	        const int tr = lin / TILE_N;
139	        const int tc = lin % TILE_N;
140	        const int gr = block_row + tr;
141	        const int gc = block_col + tc;
142	        if (gr < M && gc < N) {
143	            C[gr * N + gc] = acc[r];
144	        }
145	    }
146	}
147	
148	// torch custom-op entry: C = A @ B. All three are 2-D contiguous fp32 CUDA
149	// tensors; C is pre-allocated [M,N] by the caller (the tune_hook).
150	void gemm(torch::Tensor C, torch::Tensor A, torch::Tensor B) {
151	    TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(), "all tensors must be CUDA");
152	    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
153	                B.scalar_type() == torch::kFloat32 &&
154	                C.scalar_type() == torch::kFloat32, "all tensors must be fp32");
155	    TORCH_CHECK(A.dim() == 2 && B.dim() == 2 && C.dim() == 2, "A,B,C must be 2-D");
156	    A = A.contiguous(); B = B.contiguous(); C = C.contiguous();
157	    const int M = (int)A.size(0);
158	    const int K = (int)A.size(1);
159	    const int N = (int)B.size(1);
160	    TORCH_CHECK(B.size(0) == K, "inner dims must match: A is [M,K], B must be [K,N]");
161	    TORCH_CHECK(C.size(0) == M && C.size(1) == N, "C must be [M,N]");
162	
163	    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);
164	    dim3 block(BLOCK);
165	    gemm_tiled<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(),
166	                                C.data_ptr<float>(), M, N, K);
167	    cudaError_t err = cudaGetLastError();
168	    TORCH_CHECK(err == cudaSuccess, "gemm launch failed: ", cudaGetErrorString(err));
169	}
170	
171	}  // namespace
172	
173	TORCH_LIBRARY(sg_demo, m) {
174	    m.def("gemm(Tensor C, Tensor A, Tensor B) -> ()");
175	    m.impl("gemm", torch::kCUDA, &gemm);
176	}
