1	// examples/toy_tune_project/toy_kernel.cu
2	// ─────────────────────────────────────────────────────────────────────────
3	// A deliberately TRIVIAL, NON-grokking CUDA project used to PROVE that the
4	// SuperGrok1.5 autotuner (grokking_optimizers/compile.py) is portable: it can
5	// tune a completely different project's kernel with ZERO edits to compile.py,
6	// driven only by a TOML config + a Python project hook.
7	//
8	// One elementwise op (SAXPY: y = a*x + b) over a 1-D float tensor, registered
9	// as a torch custom op so it loads via torch.ops.load_library (the simplest
10	// "torch_op"-style extension — exactly what compile.py's discovery probe and
11	// the tune_hook both expect).
12	//
13	// THE TUNABLE KNOB is the launch block size, exposed as a -D macro:
14	//
15	//     TOY_TUNED_BLOCK     (default 256)
16	//
17	// The autotuner compiles variants with -DTOY_TUNED_BLOCK=128 / 256 / 512 /
18	// 1024 and times each. The op is NUMERICALLY IDENTICAL for every value of
19	// TOY_TUNED_BLOCK (y[i] = a*x[i] + b) — that is the whole point: the knob
20	// changes only the launch geometry / codegen / occupancy (performance), never
21	// the result. So a portable autotuner can pick the fastest block size while
22	// the strict-math oracle confirms every variant matches bit-for-bit-tolerantly.
23	//
24	// Build (standalone, for verification):
25	//   torch.utils.cpp_extension.load(name='toy_saxpy',
26	//       sources=['toy_kernel.cu'],
27	//       extra_cuda_cflags=['-DTOY_TUNED_BLOCK=256'])
28	//
29	// Build (via the autotuner): see README.md — compile.py discovers this single
30	// .cu through its zero-config Tier-1 auto-glob fallback (no launch_*.cu /
31	// models/ layout required) and threads -DTOY_TUNED_BLOCK=<v> from the search
32	// space onto the nvcc command line.
33	// ─────────────────────────────────────────────────────────────────────────
34	#include <torch/extension.h>
35	#include <c10/cuda/CUDAStream.h>
36	#include <c10/cuda/CUDAException.h>
37	#include <cuda_runtime.h>
38	
39	// ── The one tunable knob ──────────────────────────────────────────────────
40	// Overridden on the nvcc command line by the autotuner (-DTOY_TUNED_BLOCK=N)
41	// or by the standalone verification build. The #ifndef guard keeps the file
42	// compilable with no -D at all (default 256), so it builds anywhere.
43	#ifndef TOY_TUNED_BLOCK
44	#define TOY_TUNED_BLOCK 256
45	#endif
46	
47	// Compile-time sanity: a CUDA block may have at most 1024 threads. Catching a
48	// bad tuned value here turns a runtime launch failure into a clear compile
49	// error (the autotuner treats a failed compile as an infeasible config).
50	static_assert(TOY_TUNED_BLOCK >= 1 && TOY_TUNED_BLOCK <= 1024,
51	              "TOY_TUNED_BLOCK must be in [1, 1024] (CUDA max threads/block)");
52	
53	namespace {
54	
55	// Grid-stride SAXPY: y[i] = a*x[i] + b. Correct for ANY blockDim/gridDim,
56	// which is exactly why the block size is a pure performance knob.
57	__global__ void toy_saxpy_kernel(float* __restrict__ y,
58	                                 const float* __restrict__ x,
59	                                 float a, float b, int64_t n) {
60	    const int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;
61	    for (int64_t i = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
62	         i < n; i += stride) {
63	        y[i] = a * x[i] + b;
64	    }
65	}
66	
67	// In-place op: y is the mutable output (Tensor(a!) in the schema), x the input.
68	// Writing y = a*x + b. The schema marks y as aliased/mutable so compile.py's
69	// oracle snapshots y as the buffer to compare across variants.
70	void toy_saxpy(at::Tensor y, const at::Tensor& x, double a, double b) {
71	    TORCH_CHECK(x.is_cuda(), "toy::saxpy: x must be a CUDA tensor");
72	    TORCH_CHECK(y.is_cuda(), "toy::saxpy: y must be a CUDA tensor");
73	    TORCH_CHECK(x.scalar_type() == at::kFloat,
74	                "toy::saxpy: x must be float32");
75	    TORCH_CHECK(y.scalar_type() == at::kFloat,
76	                "toy::saxpy: y must be float32");
77	    TORCH_CHECK(x.numel() == y.numel(),
78	                "toy::saxpy: x and y must have the same number of elements");
79	
80	    auto xc = x.contiguous();
81	    auto yc = y.contiguous();
82	    const int64_t n = xc.numel();
83	    if (n == 0) {
84	        return;
85	    }
86	
87	    const int block = TOY_TUNED_BLOCK;                 // <-- the tuned knob
88	    int64_t grid64 = (n + block - 1) / block;
89	    // Cap the grid so the grid-stride loop covers the rest; keeps launch legal
90	    // on any size and keeps occupancy reasonable for the tiny toy workload.
91	    const int64_t kMaxGrid = 65535;
92	    const int grid = static_cast<int>(grid64 < kMaxGrid ? grid64 : kMaxGrid);
93	
94	    auto stream = at::cuda::getCurrentCUDAStream();
95	    toy_saxpy_kernel<<<grid, block, 0, stream>>>(
96	        yc.data_ptr<float>(), xc.data_ptr<float>(),
97	        static_cast<float>(a), static_cast<float>(b), n);
98	    C10_CUDA_KERNEL_LAUNCH_CHECK();
99	
100	    // If the input/output weren't already contiguous, copy the result back.
101	    if (!y.is_contiguous()) {
102	        y.copy_(yc);
103	    }
104	}
105	
106	}  // namespace
107	
108	// Register as a torch custom op so the artifact loads via
109	// torch.ops.load_library(<.so>) and the op is callable as
110	// torch.ops.toy.saxpy(y, x, a, b). The "(a!)" alias annotation tells torch
111	// (and compile.py's schema parser) that y is mutated in place — compile.py's
112	// _parse_torch_schema picks y as the snapshot buffer for numerical validation.
113	TORCH_LIBRARY(toy, m) {
114	    m.def("saxpy(Tensor(a!) y, Tensor x, float a, float b) -> ()");
115	}
116	
117	TORCH_LIBRARY_IMPL(toy, CUDA, m) {
118	    m.impl("saxpy", TORCH_FN(toy_saxpy));
119	}
